WITH filtered_accounts AS (SELECT * FROM accounts WHERE YEAR(opened_date) = 2025 AND status NOT IN ('CLOSED', 'FROZEN', 'OPEN')), summary AS (SELECT account_type, MAX(opened_date) AS last_opened_date, SUM(CASE WHEN account_type = 'LOAN' THEN balance ELSE 0 END) AS loan_balance FROM filtered_accounts GROUP BY account_type) SELECT * FROM summary WHERE loan_balance >= 77 ORDER BY last_opened_date DESC;
